import{Z as t,e as o,f as n,a0 as i}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Trello","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/miscellaneous/trello.md","filePath":"integrations/miscellaneous/trello.md","lastUpdated":1780377007000}'),r={name:"integrations/miscellaneous/trello.md"};function a(s,e,l,h,c,d){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="trello" tabindex="-1">Trello <a class="header-anchor" href="#trello" aria-label="Permalink to &quot;Trello&quot;">​</a></h1><p>Connect Trello to send submitted information to your connected account. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Miscellaneous</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Trello as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-trello-api" tabindex="-1">Step 2. Connect to the Trello API <a class="header-anchor" href="#step-2-connect-to-the-trello-api" aria-label="Permalink to &quot;Step 2. Connect to the Trello API&quot;">​</a></h3><ol><li>Go to the <a href="https://trello.com/app-key" target="_blank">Trello API Key</a> page.</li><li>Under the <strong>Developer API Keys</strong> heading, copy the <strong>Key</strong> value into the <strong>Client ID</strong> field in Formie.</li><li>Under the <strong>Allowed Origins</strong> heading, enter the value from the <strong>Redirect URI</strong> field in Formie into the text field under <strong>New Allowed Origin</strong> and hit <strong>Submit</strong>.</li><li>Under the <strong>OAuth</strong> heading, copy the <strong>Secret</strong> value into the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Trello, where you must approve Formie to access your Trello account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the destination supported by this integration, then use the variable picker to map its required fields to the appropriate form answers.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Find the resulting item in the destination you selected and compare its values with the test submission.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const u=t(r,[["render",a]]);export{p as __pageData,u as default};
